<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665">            rt_mq_send</span><span style="--shiki-light:#999999;--shiki-dark:#666666">(</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE">mq_log</span><span style="--shiki-light:#999999;--shiki-dark:#666666">,</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676">     &#x26;</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE">msg</span><span style="--shiki-light:#999999;--shiki-dark:#666666">,</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676"> sizeof</span><span style="--shiki-light:#999999;--shiki-dark:#666666">(</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE">msg</span><span style="--shiki-light:#999999;--shiki-dark:#666666">));</span></span>
